with with_gaps as (select *, case when lag(reading_ts) over (partition by device_code order by reading_ts asc, id asc) is null or reading_ts > lag(reading_ts) over (partition by device_code order by reading_ts asc, id asc) + interval 15 minutes then 1 else 0 end as new_group_flag from device_readings) select *, sum(new_group_flag) over (partition by device_code order by reading_ts asc, id asc rows between unbounded preceding and current row) as island_id from with_gaps;
